theorem Nat.toDigitsCore.eq_def✝ (base x✝ x✝¹ : ℕ) (x✝² : List Char) :
  base.toDigitsCore x✝ x✝¹ x✝² =
    match x✝, x✝¹, x✝² with
    | 0, x, ds => ds
    | fuel.succ, n, ds =>
      have d := (n % base).digitChar;
      have n' := n / base;
      if n' = 0 then d :: ds else base.toDigitsCore fuel n' (d :: ds)

